var e={sell:[["\xBFLa calculadora es una oferta definitiva?","Calcula el precio con la cotizaci\xF3n del momento y las reglas de compra de ALTER GOLD. La cifra final se confirma en tienda al comprobar el peso y la pureza de cada pieza."],["\xBFPuedo traer piezas rotas o desparejadas?","Puedes consultar la valoraci\xF3n de joyas rotas, pendientes sueltos y otras piezas de oro o plata. El equipo revisar\xE1 el metal y las caracter\xEDsticas de cada pieza."],["\xBFQu\xE9 ocurre con las piedras?","El peso de piedras y elementos que no sean el metal seleccionado debe revisarse por separado. La calculadora no realiza una valoraci\xF3n gemol\xF3gica."],["\xBFTengo que vender despu\xE9s de la tasaci\xF3n?","No. Valoramos tus piezas sin compromiso de venta y decides despu\xE9s. Para vender, solo necesitas tu DNI o pasaporte en vigor."]],shop:[["\xBFLa fotograf\xEDa corresponde a la joya?","S\xED. Cada ficha muestra la pieza que vas a recibir. Si quieres ver un detalle concreto, p\xEDdenos m\xE1s fotograf\xEDas o ven a verla a la tienda."],["\xBFEst\xE1 disponible la pieza que veo en la web?","Cada pieza es \xFAnica y tambi\xE9n puede venderse en nuestras tiendas. Si una te interesa, conf\xEDrmanos que sigue disponible por WhatsApp o por tel\xE9fono, con la referencia que aparece en su ficha."],["\xBFC\xF3mo s\xE9 mi talla?",'Consulta la medida indicada en la ficha y la <a href="#/guia-tallas">gu\xEDa de medidas</a>. Si tienes dudas, podemos ayudarte en tienda antes de elegir. No todas las piezas pueden ajustarse.'],["\xBFLa entreg\xE1is lista para regalar?","S\xED. Te entregamos tu joya en su estuche, con una bolsa de ALTER GOLD."]],order:[["\xBFC\xF3mo puedo pagar?","Con tarjeta de cr\xE9dito o d\xE9bito, en la pasarela de pago segura, o a plazos con Klarna, sujeto a su aprobaci\xF3n. Los datos de pago se introducen al final de la compra."],["\xBFPuedo recoger mi compra en tienda?","S\xED, sin coste. Al finalizar la compra, elige recogida en Gandia (Av. de la Rep\xFAblica Argentina, 15) o en Oliva (C. del Pare Antoni Salelles, 3) y te avisaremos cuando la pieza est\xE9 lista. Consulta el horario antes de venir."],["\xBFHac\xE9is env\xEDos?","La cobertura, el coste y el plazo del env\xEDo a domicilio est\xE1n pendientes de confirmar seg\xFAn el destino: preg\xFAntanos antes de comprar. La recogida en nuestras tiendas de Gandia y Oliva no tiene coste."],["\xBFPuedo devolver una joya comprada online?",'S\xED. En las compras online tienes 14 d\xEDas naturales desde que recibes la pieza para desistir, sin necesidad de dar explicaciones, salvo que se haya ajustado o personalizado a tu medida. Escr\xEDbenos a <a href="mailto:info@altergold.es">info@altergold.es</a> o ll\xE1manos al <a href="tel:+34961126527">961 12 65 27</a> y te indicaremos c\xF3mo devolverla.'],["\xBFQu\xE9 garant\xEDa tienen las joyas?","Como en cualquier compra a un comercio, tienes la garant\xEDa legal si la joya no se corresponde con lo que se describe en su ficha. Si tienes dudas sobre una pieza concreta, preg\xFAntanos antes de comprar."]],pawn:[["\xBFEn qu\xE9 se diferencia empe\xF1ar de vender?","En una venta transmites la pieza de acuerdo con las condiciones aceptadas. En un empe\xF1o, la pieza act\xFAa como garant\xEDa y la posibilidad de recuperarla depende del contrato, los pagos y los plazos acordados."],["\xBFCu\xE1nto cuesta recuperar mi joya?","Devuelves lo prestado m\xE1s el coste del empe\xF1o, que va del 7 % al 24 % seg\xFAn la parte del valor que recibes y el plazo elegido. La calculadora te muestra el total antes de venir."],["\xBFQu\xE9 pasa si no puedo cumplir el plazo?","Consulta las condiciones de vencimiento, renovaci\xF3n y consecuencias del impago antes de firmar. El equipo debe explicarte las opciones aplicables a tu contrato."]],sellHelp:[["\xBFC\xF3mo comprob\xE1is el oro?",'Delante de ti: comprobamos la pureza con piedra de toque, fluorescencia de rayos X o densidad hidrost\xE1tica, seg\xFAn la pieza, y la pesamos en b\xE1sculas homologadas. Si quieres saber qu\xE9 indican los sellos de tus joyas, lee <a href="#/articulos/que-significan-los-contrastes-o-sellos-del-oro">qu\xE9 significan los contrastes del oro</a>.'],["\xBFC\xF3mo cobro?",'Al firmar: en efectivo hasta 999 \u20AC y por transferencia a partir de 1.000 \u20AC. Te explicamos <a href="#/articulos/que-documentacion-necesito-para-vender-oro">qu\xE9 documentaci\xF3n necesitas para vender oro</a>.']]},l=[...e.shop,...e.order,...e.sell,...e.sellHelp,...e.pawn],t={Anillos:[["\xBFC\xF3mo s\xE9 cu\xE1l es mi talla?",'Consulta la <a href="#/guia-tallas#anillos">gu\xEDa de tallas de anillos</a>: compara el di\xE1metro interior de un anillo que te quede bien con la tabla. Si tienes dudas, te medimos el dedo en tienda.'],["\xBFQu\xE9 significa oro de 18 k?","Que la pieza tiene 750 mil\xE9simas de oro puro: 18 de cada 24 partes. Es la ley m\xE1s habitual en joyer\xEDa en Espa\xF1a y la que mejor equilibra pureza y resistencia."],["\xBFSe puede cambiar la talla?","Depende del dise\xF1o: un aro liso suele admitirlo y uno con piedras alrededor, no siempre. Preg\xFAntanos antes de comprar y lo revisamos."]],Pendientes:[["\xBFQu\xE9 cierre es m\xE1s c\xF3modo?","El de presi\xF3n es el m\xE1s sencillo de poner; el catal\xE1n (de bisagra) sujeta muy bien los aros. Si la ficha no indica el cierre de una pieza, preg\xFAntanos antes de comprar."],["\xBFEl oro de ley da alergia?","El oro de 18 k suele tolerarse bien. Las reacciones se deben sobre todo al n\xEDquel, que llevan algunas aleaciones de oro blanco. Si tienes la piel sensible, cons\xFAltanos antes de comprar."],["\xBFC\xF3mo los guardo?",'Por separado, en un compartimento o bolsa suave, para que no se rayen ni se pierdan los cierres. Tienes m\xE1s consejos en <a href="#/guia-cuidados">cuidado de las joyas</a>.']],Cadenas:[["\xBFQu\xE9 largo elijo?",'Entre 40 y 45 cm queda a la altura del cuello y la clav\xEDcula; a partir de 50 cm cae sobre el pecho. Tienes todas las medidas en la <a href="#/guia-tallas#collares">gu\xEDa de tallas de collares</a>.'],["\xBFQu\xE9 diferencia hay entre una barbada y una veneciana?","La barbada tiene eslabones planos y torcidos que reflejan mucha luz; la veneciana, eslabones cuadrados que forman una cadena firme, ideal para colgantes."],["\xBFPuedo llevar un colgante con cualquier cadena?","Casi siempre, pero el grosor de la cadena debe pasar por la anilla del colgante. Te ayudamos a combinarlos en tienda."]],Pulseras:[["\xBFC\xF3mo mido mi mu\xF1eca?",'Rod\xE9ala con una cinta m\xE9trica justo por encima del hueso y a\xF1ade 2 cm. Compara el resultado en la <a href="#/guia-tallas#pulseras">gu\xEDa de tallas de pulseras</a>.'],["\xBFSe puede acortar una pulsera?","Muchas cadenas s\xED, quitando eslabones. Cons\xFAltanos con la referencia de la pieza."],["\xBFSe puede llevar todos los d\xEDas?","El oro de ley no se oxida. Para que conserve el brillo, qu\xEDtatela para hacer deporte o usar productos de limpieza."]],Colgantes:[["\xBFEl colgante incluye cadena?","Preg\xFAntanos antes de comprar si no lo ves claro en la ficha. Si no la incluye, te ayudamos a elegir una cadena del largo y grosor adecuados."],["\xBFQu\xE9 largo de cadena le va mejor?",'Los colgantes peque\xF1os lucen a 40 o 45 cm; los grandes, a partir de 50 cm. Mira la <a href="#/guia-tallas#collares">gu\xEDa de tallas de collares</a>.'],["\xBFPuedo grabarlo?","Muchos colgantes lisos lo admiten. Preg\xFAntanos por la pieza que te guste."]],Gargantillas:[["\xBFQu\xE9 diferencia hay entre gargantilla y collar?","La gargantilla es corta y se ajusta al cuello, normalmente entre 35 y 42 cm; el collar es m\xE1s largo y cae sobre el escote."],["\xBFQu\xE9 escote le va mejor?",'Los escotes redondos, barco y en V. Tienes los diez escotes en la <a href="#/guia-tallas#collares">gu\xEDa de tallas de collares</a>.'],["\xBFC\xF3mo la cuido?",'Gu\xE1rdala estirada o colgada para que no se enrede, y qu\xEDtatela para dormir. Tienes m\xE1s consejos en <a href="#/guia-cuidados">cuidado de las joyas</a>.']],Cruces:[["\xBFQu\xE9 cadena le pongo a una cruz?","Para cruces peque\xF1as, una cadena fina de 40 a 45 cm; para las de mayor tama\xF1o, una cadena firme como la veneciana o la barbada."],["\xBFLas cruces son de oro macizo?","La ficha indica la ley y el peso de cada pieza. Las cruces de este cat\xE1logo son de oro de ley."],["\xBFEs un buen regalo de comuni\xF3n o bautizo?","Es uno de los m\xE1s tradicionales. Si quieres, te la entregamos en su estuche, lista para regalar."]]};var a=[{image:"banner-joyas-ocasion.webp",label:"Joyer\xEDa de ocasi\xF3n y compra de oro en Gandia y Oliva",title:"Piezas \xFAnicas, <em>con historia</em>",text:"Joyas restauradas y certificadas, elegidas una a una. El lujo sostenible, a tu alcance.",doors:[["/tienda","Comprar joyas"],["scroll","Valorar mis piezas"]],actions:[]},{image:"banner-vender-oro.webp",label:"Compra de oro en Gandia y Oliva",title:"Tu oro, <em>liquidez inmediata</em>",text:"Tasamos con la cotizaci\xF3n del d\xEDa, con total transparencia, seguridad y discreci\xF3n. Pago al instante.",actions:[["scroll","Valorar mis piezas"],["/vender-oro","Compra de oro"]]},{image:"banner-empeno.webp",label:"Empe\xF1o de joyas",title:"Liquidez al instante, <em>sin desprenderte de tus joyas</em>",short:"Liquidez <em>sin vender tus joyas</em>",text:"Condiciones claras y discreci\xF3n absoluta. Recupera tus piezas al final del plazo.",actions:[["/empenos","Calcular mi empe\xF1o"]]},{image:"banner-inversion.webp",label:"Lingotes de inversi\xF3n",title:"Inversi\xF3n refugio: <em>protege tu patrimonio</em>",text:"Oro y plata de inversi\xF3n f\xEDsica certificada LBMA. Un valor tangible frente a la inflaci\xF3n.",actions:[["/inversion","Empezar a invertir"]]},{image:"banner-plata.webp",label:"Compra de plata",title:"El valor real <em>de tu plata</em>",text:"Compramos joyas, monedas y objetos de plata, con la cotizaci\xF3n actualizada al momento.",actions:[["/vender-plata","Tasar mi plata"]]},{image:"banner-cajas-seguridad.webp",label:"Cajas de seguridad",title:"Lo m\xE1s valioso, <em>en privado</em>",text:"Alquiler de cajas de seguridad con la m\xE1xima privacidad y seguridad.",actions:[["/cajas-seguridad","Reservar mi caja"]]},{image:"banner-atencion.webp",label:"Atenci\xF3n multiling\xFCe",title:"Te atendemos <em>en tu idioma</em>",text:"En tienda y por tel\xE9fono, en espa\xF1ol, ingl\xE9s, italiano, franc\xE9s y ruso.",actions:[["/contacto","Contactar"]]}];var d=[{...a[1],doors:[["scroll","Valorar mis piezas"],["/tienda","Ver joyas disponibles"]],actions:[["/vender-oro","Compra de oro"]]},{...a[0],label:"Joyer\xEDa de ocasi\xF3n",doors:void 0,actions:[["/tienda","Ver la colecci\xF3n"]]},...a.slice(2)];function U(o,s=-1){return o.map(([i,n],r)=>`<details class="accordion" ${r===s?"open":""}><summary>${i}</summary><div class="details-body">${n}</div></details>`).join("")}export{e as a,t as b,U as c};
